package com.oms.order.service;
import com.oms.messaging.*;
import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.support.StaticListableBeanFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;
class ExchangeIntakeMessageTest {
 static final String C="VERIFY";ExchangeServiceTest fixture;JdbcTemplate db;OrderRepository repo;MessageOutbox out;ExchangeSync sync;PlatformExchangeService source;ExchangePullMessage pull;ExchangeConvertMessage convert;ExchangeService calls;
 @BeforeAll static void init(){ExchangeServiceTest.start();}
 @BeforeEach void setup(){fixture=new ExchangeServiceTest();fixture.reset();db=ExchangeServiceTest.db;repo=fixture.repo;db.update("DELETE FROM oms_exchange_sync_item");db.update("DELETE FROM oms_message_attempt WHERE company_code=?",C);db.update("DELETE FROM oms_message_outbox WHERE company_code=?",C);out=new MessageOutbox();out.db=db;ReflectionTestUtils.setField(out,"transactionManager",new DataSourceTransactionManager(db.getDataSource()));ReflectionTestUtils.setField(out,"service","order");StaticListableBeanFactory beans=new StaticListableBeanFactory();beans.addBean("outbox",out);ReflectionTestUtils.setField(repo,"messages",beans.getBeanProvider(MessageOutbox.class));source=new PlatformExchangeService(repo,fixture.service);sync=new ExchangeSync();sync.repository=repo;calls=spy(fixture.service);sync.exchanges=calls;sync.platformExchanges=source;pull=new ExchangePullMessage();pull.sync=sync;pull.platform=fixture.bridge;convert=new ExchangeConvertMessage();convert.source=source;convert.sync=sync;db.update("UPDATE oms_exchange_config SET enabled=0,auto_convert=1");when(fixture.bridge.rateKeys(anyString(),anyLong(),anyString())).thenReturn(R.ok(Arrays.asList(hash("app"),hash("shop"))));}
 @AfterEach void stop(){sync.close();}
 long task(String ids){return number(sync.submit(C,map("channel_id",1,"dispute_ids",ids,"request_key",token(),"start_time","2026-10-16 00:00:00","end_time","2026-10-17 00:00:00"),"test"),"id");}
 Map<String,Object> payload(int i){Map<String,Object> p=fixture.source();p.put("dispute_id","771000"+i);return p;}
 void detail(int i){doReturn(map("exchange",payload(i))).when(calls).call(eq(C),eq(1L),eq("DETAIL"),argThat(a->text(payload(i),"dispute_id").equals(text(a,"dispute_id"))));}
 long ingest(int i){return number(source.ingest(C,1,payload(i),"test"),"id");}
 Map<String,Object> message(String type,long id){return db.queryForMap("SELECT * FROM oms_message_outbox WHERE company_code=? AND message_type=? AND business_id=? ORDER BY id DESC LIMIT 1",C,type,String.valueOf(id));}
 long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE company_code=?",Long.class,C);}
 MessageRuntime runtime(MessageHandler h){MessageRuntime r=new MessageRuntime();ReflectionTestUtils.setField(r,"outbox",out);ReflectionTestUtils.setField(r,"handlers",Collections.singletonList(h));ReflectionTestUtils.setField(r,"tenants",mock(com.oms.common.tenant.TenantRouting.class));return r;}
 @Test void taskIdsAndNotificationAreAtomic(){assertThrows(RuntimeException.class,()->out.tx(()->{task("7710001,7710002");throw new RuntimeException("rollback");}));assertEquals(0,count("oms_exchange_sync"));assertEquals(0,count("oms_exchange_sync_item"));assertEquals(0,count("oms_message_outbox"));}
 @Test void eachDeliveryHasOnePlatformCallAndListPageIsNotFetchedAgainAfterRestart(){long id=task("");List<Map<String,Object>> first=new ArrayList<>();for(int i=1;i<=30;i++){first.add(payload(i));detail(i);}detail(31);doReturn(map("records",first),map("records",Collections.singletonList(payload(31)))).when(calls).call(eq(C),eq(1L),eq("LIST"),anyMap());Map<String,Object> m=message("EXCHANGE_PULL",id);assertEquals("WAITING",pull.handle(C,m).state);assertEquals(0,count("oms_platform_exchange"));verify(calls,times(1)).call(eq(C),eq(1L),eq("LIST"),anyMap());ExchangePullMessage restarted=new ExchangePullMessage();restarted.sync=sync;restarted.platform=fixture.bridge;for(int i=1;i<=30;i++)restarted.handle(C,m);assertEquals(30,count("oms_platform_exchange"));assertEquals(2,number(sync.rawTask(C,id,false),"page_no"));assertEquals("LIST",text(sync.rawTask(C,id,false),"phase"));restarted.handle(C,m);assertEquals("SUCCESS",restarted.handle(C,m).state);assertEquals(31,count("oms_platform_exchange"));verify(calls,times(2)).call(eq(C),eq(1L),eq("LIST"),anyMap());verify(calls,times(31)).call(eq(C),eq(1L),eq("DETAIL"),anyMap());}
 @Test void committedPageCannotLoseConversionNotifications(){long id=task("7710001");detail(1);doThrow(new IllegalStateException("conversion unavailable")).when(fixture.bridge).call(anyString(),anyLong(),anyMap(),anyString());assertEquals("SUCCESS",pull.handle(C,message("EXCHANGE_PULL",id)).state);assertEquals(1,count("oms_platform_exchange"));long p=db.queryForObject("SELECT id FROM oms_platform_exchange",Long.class);assertNotNull(message("EXCHANGE_CONVERT",p));assertEquals(0,count("oms_exchange"));verifyNoInteractions(fixture.warehouse);}
 @Test void malformedListRollsBackAllIdsAndLeavesPageUnchanged(){long id=task("");doReturn(map("records",Arrays.asList(payload(1),map("dispute_id","bad")))).when(calls).call(eq(C),eq(1L),eq("LIST"),anyMap());assertEquals("WAITING",pull.handle(C,message("EXCHANGE_PULL",id)).state);assertEquals(0,count("oms_exchange_sync_item"));assertEquals("LIST",text(sync.rawTask(C,id,false),"phase"));}
 @Test void partialDetailFailureRetainsSuccessAndManualRetryOnlyQueriesFailedItem(){long id=task("7710001,7710002");detail(1);doThrow(new IllegalArgumentException("source temporarily unavailable")).when(calls).call(eq(C),eq(1L),eq("DETAIL"),argThat(a->"7710002".equals(text(a,"dispute_id"))));Map<String,Object> old=message("EXCHANGE_PULL",id);pull.handle(C,old);MessageRuntime r=runtime(pull);db.update("UPDATE oms_message_outbox SET business_attempts=7 WHERE event_id=?",old.get("event_id"));r.execute(C,out.row(C,text(old,"event_id")),"MQ");assertEquals("FAILED",sync.task(C,id).get("state"));assertEquals(1,count("oms_platform_exchange"));detail(2);r.retry(C,text(old,"event_id"),"test","平台查询已恢复");Map<String,Object> latest=message("EXCHANGE_PULL",id);assertEquals(old.get("event_id"),latest.get("parent_event_id"));r.execute(C,latest,"MQ");assertEquals("COMPLETED",sync.task(C,id).get("state"));verify(calls,times(1)).call(eq(C),eq(1L),eq("DETAIL"),argThat(a->"7710001".equals(text(a,"dispute_id"))));assertEquals(2,count("oms_platform_exchange"));}
 @Test void repeatedDeliveryAfterCompletionDoesNotReadAgain(){long id=task("7710001");detail(1);Map<String,Object> m=message("EXCHANGE_PULL",id);assertEquals("SUCCESS",pull.handle(C,m).state);assertEquals("SUCCESS",pull.handle(C,m).state);verify(calls,times(1)).call(eq(C),eq(1L),eq("DETAIL"),anyMap());}
 @Test void shopLeaseWaitPreservesRetryBudgetAndNeverCallsPlatform(){long id=task("7710001");long p=ingest(1);assertTrue(sync.claim(C,1,"busy"));try{assertTrue(pull.handle(C,message("EXCHANGE_PULL",id)).preserveAttempts);assertTrue(convert.handle(C,message("EXCHANGE_CONVERT",p)).preserveAttempts);verify(calls,never()).call(anyString(),anyLong(),anyString(),anyMap());}finally{sync.release(C,1,"busy");}}
 @Test void lateOriginalWaitsThenAssociatesWithoutSpendingFailureBudget(){long p=ingest(1);db.update("DELETE FROM oms_order WHERE company_code=?",C);Map<String,Object> m=message("EXCHANGE_CONVERT",p);MessageRuntime r=runtime(convert);db.update("UPDATE oms_message_outbox SET business_attempts=7 WHERE event_id=?",m.get("event_id"));r.execute(C,out.row(C,text(m,"event_id")),"MQ");assertEquals("WAITING",out.row(C,text(m,"event_id")).get("process_state"));assertEquals(7,number(out.row(C,text(m,"event_id")),"business_attempts"));db.update("INSERT INTO oms_order(id,company_code,order_sn,channel_id,platform_order_id,platform_tid,inventory_status,payment,review_status) VALUES (?,'VERIFY','SO_EXCHANGE',1,?,'987654321012345678','RESERVED',25,'APPROVED')",fixture.order,fixture.platform);db.update("UPDATE oms_message_outbox SET next_process_at=NOW() WHERE event_id=?",m.get("event_id"));r.execute(C,out.row(C,text(m,"event_id")),"MQ");assertEquals("SUCCESS",source.row(C,p,false).get("conversion_state"));assertEquals(fixture.order,number(fixture.service.row(C,number(source.row(C,p,false),"business_exchange_id"),false),"order_id"));}
 @Test void newerWithdrawalInvalidatesQueuedOldConversion(){long p=ingest(1);Map<String,Object> old=message("EXCHANGE_CONVERT",p),closed=payload(1);closed.put("modified","2026-10-17 10:00:00");closed.put("status","14");source.ingest(C,1,closed,"test");assertEquals("SUCCESS",convert.handle(C,old).state);assertEquals("SKIPPED",source.row(C,p,false).get("conversion_state"));assertEquals(0,count("oms_exchange"));}
 @Test void sameSourceAndOldVersionsDoNotProduceAnotherWakeup(){long p=ingest(1);Map<String,Object> m=message("EXCHANGE_CONVERT",p);source.ingest(C,1,payload(1),"test");Map<String,Object> old=payload(1);old.put("modified","2026-10-01 00:00:00");source.ingest(C,1,old,"test");assertEquals(m.get("event_id"),message("EXCHANGE_CONVERT",p).get("event_id"));}
 @Test void duplicateConversionRetainsOriginalOrderAndNeverGuessesSku(){long p=ingest(1);Map<String,Object> m=message("EXCHANGE_CONVERT",p);convert.handle(C,m);convert.handle(C,m);assertEquals(1,count("oms_exchange"));assertEquals(1,count("oms_order"));Map<String,Object> b=fixture.service.row(C,number(source.row(C,p,false),"business_exchange_id"),false);assertEquals("",text(b,"target_sku"));assertNull(b.get("approved_version"));verifyNoInteractions(fixture.warehouse);}
 @Test void invalidNewSourceStopsOlderNotificationAndRetainsRawSnapshot(){long p=ingest(1);Map<String,Object> m=message("EXCHANGE_CONVERT",p),bad=payload(1);bad.put("num",0);source.ingest(C,1,bad,"test");assertEquals("SUCCESS",convert.handle(C,m).state);assertEquals("INVALID",source.row(C,p,false).get("source_state"));assertEquals(2,count("oms_platform_exchange_snapshot"));assertEquals(0,count("oms_exchange"));}
 @Test void manualConversionWithAutoOffUsesQueueAndIsIdempotent(){db.update("UPDATE oms_exchange_config SET auto_convert=0");long p=ingest(1);assertEquals(0,count("oms_message_outbox"));source.requestConvert(C,p,"test");source.requestConvert(C,p,"test");assertEquals(1,count("oms_message_outbox"));assertEquals("SUCCESS",convert.handle(C,message("EXCHANGE_CONVERT",p)).state);}
 @Test void scannerOnlyPublishesAndNeverCallsPlatform(){task("7710001");long before=count("oms_message_outbox");sync.shop(C,1);sync.shop(C,1);assertEquals(before,count("oms_message_outbox"));verify(calls,never()).call(anyString(),anyLong(),anyString(),anyMap());}
 @Test void rateKeysComeFromTrustedChannelAndTerminalTasksNeedNoQuota(){long id=task("7710001");detail(1);Map<String,Object> m=message("EXCHANGE_PULL",id);assertEquals(Arrays.asList(hash("app"),hash("shop")),pull.rateKeys(C,m));pull.handle(C,m);assertTrue(pull.rateKeys(C,m).isEmpty());verify(fixture.bridge,times(1)).rateKeys(eq(C),eq(1L),anyString());}
 @Test void companyScopeAndDisabledTenantCannotStartNewIntake(){long id=task("7710001");assertThrows(IllegalArgumentException.class,()->sync.rawTask("OTHER",id,false));MessageRuntime r=runtime(pull);com.oms.common.tenant.TenantRouting tenants=mock(com.oms.common.tenant.TenantRouting.class);when(tenants.open(C)).thenThrow(new IllegalArgumentException("disabled"));ReflectionTestUtils.setField(r,"tenants",tenants);Map<String,Object> m=message("EXCHANGE_PULL",id);assertThrows(IllegalArgumentException.class,()->r.execute(C,m,"MQ"));assertEquals("PENDING",out.row(C,text(m,"event_id")).get("process_state"));}
}
